// Collecte les 4 feuilles déjà lues en amont et ajoute le tag _sheet
const sheets = [
  { node: '📋 Lire NTC', name: 'NTC' },
  { node: '📋 Lire AD',  name: 'AD'  },
  { node: '📋 Lire CC',  name: 'CC'  },
  { node: '📋 Lire REM', name: 'REM' }
];

const results = [];
for (const s of sheets) {
  try {
    for (const i of $(s.node).all()) {
      results.push({ json: { ...i.json, _sheet: s.name } });
    }
  } catch(e) {}
}
return results;

const NIV_MAP = {
  0: '1', 1: '1',
  2: '2', 3: '2',
  4: '3', 5: '3', 6: '3',
  7: '+', 8: '+', 9: '+'
};

const results = [];

for (const item of $input.all()) {
  const row = item.json;
  const allKeys = Object.keys(row);

  // Mapping manuel par index de colonne (A=0, B=1, C=2, D=3...)
  const colValues = allKeys.sort().map(k => row[k]);
  const session = (colValues[0] || '').toString().trim();
  const nom     = (colValues[1] || '').toString().trim();
  const prenom  = (colValues[2] || '').toString().trim();

  // Chercher le mail : première colonne contenant @
  let mail = '';
  for (const val of colValues) {
    const strVal = (val || '').toString().trim();
    if (strVal.includes('@')) {
      mail = strVal;
      break;
    }
  }

  if (!nom || nom === 'NOM' || nom === 'Session') continue;

  const feuille = (row['_sheet'] || '').toString().trim();

  // Les colonnes "Mail niv" sont aux indices : 6, 9, 12, 15, 18, 21, 24, 27, 30, 33
  // (chaque groupe de 3 : Date / Motif / Mail niv)
  const mailNivIndices = [6, 9, 12, 15, 18, 21, 24, 27, 30, 33];

  mailNivIndices.forEach((colIdx, idx) => {
    const val = colValues[colIdx];
    const isTRUE = (val === true || val === 'TRUE' || val === 'True' || val === 'true' || val === 1 || val === '1');
    if (!isTRUE) return;

    const niveau   = NIV_MAP[idx] || '+';
    const dateVal  = (colValues[colIdx - 2] || '').toString().trim();
    const motifVal = (colValues[colIdx - 1] || '').toString().trim();

    // Filtrer : ne garder que si la case est cochée ET le motif est vide
    if (motifVal !== '') return;

    const nomPrenom = `${nom} ${prenom}`;
    const sujet = `Mail niv${niveau} - apprenant ${nomPrenom}`;
    const corps = `Bonjour,\n\nSuivi d'absence - Niveau ${niveau}\n\nApprenant(e) : ${nomPrenom}\nSession      : ${session} (${feuille})\nDate absence : ${dateVal}\nMotif        : ${motifVal}\n\nCordialement`;
    const uniqueKey = `${feuille}_${session}_${nom}_${prenom}_abs${idx}`;

    results.push({ json: { sujet, corps, nom, prenom, session, feuille, niveau, dateAbs: dateVal, motif: motifVal, uniqueKey, mail } });
  });
}

return results;

const store = $getWorkflowStaticData('global');
if (!store.doneKeys) store.doneKeys = [];

const newItems = [];
for (const item of $input.all()) {
  const k = item.json.uniqueKey;
  if (!store.doneKeys.includes(k)) {
    store.doneKeys.push(k);
    newItems.push(item);
  }
}

if (store.doneKeys.length > 5000) {
  store.doneKeys = store.doneKeys.slice(-3000);
}

return newItems;
